package com.kareem.lifeos;

import android.app.Activity;
import android.content.Intent;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.graphics.Typeface;
import android.os.Bundle;
import android.speech.RecognizerIntent;
import android.view.Gravity;
import android.view.inputmethod.EditorInfo;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public final class AskLifeOsActivity extends Activity {
    private static final int VOICE=51;private LinearLayout answers;private EditText input;private volatile boolean running;
    @Override public void onCreate(Bundle s){super.onCreate(s);render();}
    private void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(LifeOsUi.BG);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(LifeOsUi.dp(this,16),LifeOsUi.dp(this,9),LifeOsUi.dp(this,10),LifeOsUi.dp(this,7));TextView title=LifeOsUi.text(this,"Ask LifeOS",21,LifeOsUi.TEXT);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);head.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button history=LifeOsUi.iconButton(this,"↶");history.setContentDescription("Recent questions");history.setOnClickListener(v->showHistory());head.addView(history,new LinearLayout.LayoutParams(LifeOsUi.dp(this,40),LifeOsUi.dp(this,40)));Button more=LifeOsUi.iconButton(this,"⋮");more.setContentDescription("More");more.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));head.addView(more,new LinearLayout.LayoutParams(LifeOsUi.dp(this,36),LifeOsUi.dp(this,40)));root.addView(head);ScrollView sc=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(LifeOsUi.dp(this,16),LifeOsUi.dp(this,3),LifeOsUi.dp(this,16),LifeOsUi.dp(this,10));android.view.View orb=LifeOsUi.orb(this);body.addView(orb,new LinearLayout.LayoutParams(-1,LifeOsUi.dp(this,150)));TextView hello=LifeOsUi.text(this,"How can I help you?",22,LifeOsUi.TEXT);hello.setTypeface(Typeface.DEFAULT,Typeface.BOLD);hello.setGravity(Gravity.CENTER);body.addView(hello);TextView sub=LifeOsUi.text(this,"Ask. Plan. Decide. Do.",12,LifeOsUi.MUTED);sub.setGravity(Gravity.CENTER);sub.setPadding(0,LifeOsUi.dp(this,3),0,LifeOsUi.dp(this,15));body.addView(sub);for(String q:new String[]{"What needs my attention today?","Summarize my conversations with Ahmed this week.","Find the latest gypsum board price and compare it.","What did I decide about the car?","Draft a reply to GLIO with my car details."}){Button b=LifeOsUi.button(this,q+"   ›");b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setPadding(LifeOsUi.dp(this,13),0,LifeOsUi.dp(this,13),0);b.setOnClickListener(v->{input.setText(q);ask(q);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,LifeOsUi.dp(this,49));p.setMargins(0,0,0,LifeOsUi.dp(this,7));body.addView(b,p);}answers=new LinearLayout(this);answers.setOrientation(LinearLayout.VERTICAL);answers.setPadding(0,LifeOsUi.dp(this,6),0,0);body.addView(answers);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout composerWrap=new LinearLayout(this);composerWrap.setGravity(Gravity.CENTER_VERTICAL);composerWrap.setPadding(LifeOsUi.dp(this,14),LifeOsUi.dp(this,6),LifeOsUi.dp(this,14),LifeOsUi.dp(this,6));LinearLayout pill=new LinearLayout(this);pill.setGravity(Gravity.CENTER_VERTICAL);pill.setPadding(LifeOsUi.dp(this,13),0,LifeOsUi.dp(this,5),0);pill.setBackground(LifeOsUi.round(this,LifeOsUi.SURFACE_2,LifeOsUi.BORDER,25));input=new EditText(this);input.setHint("Ask anything…");input.setHintTextColor(LifeOsUi.MUTED);input.setTextColor(LifeOsUi.TEXT);input.setTextSize(13);input.setSingleLine(true);input.setImeOptions(EditorInfo.IME_ACTION_SEND);input.setBackgroundColor(Color.TRANSPARENT);input.setPadding(0,0,0,0);pill.addView(input,new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,45),1));Button mic=LifeOsUi.iconButton(this,"♩");mic.setTextSize(15);mic.setContentDescription("Voice question");mic.setOnClickListener(v->startVoice());pill.addView(mic,new LinearLayout.LayoutParams(LifeOsUi.dp(this,35),LifeOsUi.dp(this,35)));composerWrap.addView(pill,new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,47),1));Button send=LifeOsUi.primary(this,"↑");send.setTextSize(18);send.setBackground(LifeOsUi.round(this,LifeOsUi.BLUE,LifeOsUi.BLUE,40));send.setOnClickListener(v->ask(input.getText().toString()));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(LifeOsUi.dp(this,47),LifeOsUi.dp(this,47));sp.setMargins(LifeOsUi.dp(this,8),0,0,0);composerWrap.addView(send,sp);input.setOnEditorActionListener((v,id,e)->{if(id==EditorInfo.IME_ACTION_SEND){ask(input.getText().toString());return true;}return false;});root.addView(composerWrap);root.addView(LifeOsUi.bottomNav(this,AskLifeOsActivity.class));setContentView(root);}
    private void ask(String q){q=q==null?"":q.trim();if(q.isEmpty()||running)return;saveHistory(q);running=true;answers.removeAllViews();LinearLayout loading=LifeOsUi.card(this);loading.addView(LifeOsUi.text(this,"Thinking with your LifeOS memory…",11,LifeOsUi.MUTED));answers.addView(loading);final String question=q;new Thread(()->{String answer;try{String context=LifeIntelligenceEngine.context(this,question);if(BackgroundModelManager.isReadyFast(this)){File model=BackgroundModelManager.modelFile(this);String prompt="You are LifeOS, Karim's private personal intelligence. Answer the QUESTION using ONLY the grounded CONTEXT below. Address Karim directly as 'you'; never say 'the user'. Be concise, useful and explicit about uncertainty. Do not invent missing facts. Maximum 8 short sentences.\nQUESTION:\n"+question+"\n\n"+context;answer=BackgroundSemanticRuntime.generateFreeform(this,model.getAbsolutePath(),prompt);}else answer=LifeIntelligenceEngine.fallbackAnswer(this,question);}catch(Throwable e){answer=LifeIntelligenceEngine.fallbackAnswer(this,question);}final String out=UserFacingText.humanize(answer);runOnUiThread(()->{running=false;answers.removeAllViews();LinearLayout card=LifeOsUi.card(this);TextView k=LifeOsUi.text(this,"LIFE INTELLIGENCE",9,LifeOsUi.BLUE);k.setTypeface(Typeface.DEFAULT,Typeface.BOLD);card.addView(k);TextView a=LifeOsUi.text(this,out,12,LifeOsUi.TEXT);a.setPadding(0,LifeOsUi.dp(this,6),0,0);card.addView(a);answers.addView(card);});},"lifeos-ask").start();}
    private void showHistory(){answers.removeAllViews();List<String> xs=history();if(xs.isEmpty()){answers.addView(LifeOsUi.text(this,"No recent questions yet.",11,LifeOsUi.MUTED));return;}TextView h=LifeOsUi.text(this,"Recent questions",12,LifeOsUi.TEXT);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);h.setPadding(0,0,0,LifeOsUi.dp(this,6));answers.addView(h);for(String q:xs){Button b=LifeOsUi.button(this,q+"  ›");b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setOnClickListener(v->{input.setText(q);ask(q);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,LifeOsUi.dp(this,44));p.setMargins(0,0,0,LifeOsUi.dp(this,6));answers.addView(b,p);}}
    private void saveHistory(String value){String s=value==null?"":value.trim();if(s.isEmpty())return;ArrayList<String> h=new ArrayList<>(history());h.remove(s);h.add(0,s);while(h.size()>6)h.remove(h.size()-1);prefs().edit().putString("history",android.text.TextUtils.join("\u001f",h)).apply();}
    private List<String> history(){String raw=prefs().getString("history","");if(raw==null||raw.isEmpty())return new ArrayList<>();return new ArrayList<>(Arrays.asList(raw.split("\u001f")));}
    private SharedPreferences prefs(){return getSharedPreferences("lifeos_ask",MODE_PRIVATE);}
    private void startVoice(){try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);startActivityForResult(i,VOICE);}catch(Throwable ignored){}}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==VOICE&&resultCode==RESULT_OK&&data!=null){ArrayList<String> xs=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(xs!=null&&!xs.isEmpty()){input.setText(xs.get(0));ask(xs.get(0));}}}
}
